function updateOnboarding(){
  const panel=$('#onboardingPanel');if(!panel)return;
  const checks=[
    !!state.user,
    !!state.productionConnected,
    !!(state.sites&&state.sites.length),
    !!((state.schedule&&state.schedule.length)||(state.pins&&state.pins.length))
  ];
  ['Account','Pinterest','Website','FirstPin'].forEach((n,i)=>{const el=$('#onboard'+n);if(el)el.className='step-dot '+(checks[i]?'done':'')});
  const count=checks.filter(Boolean).length,status=$('#onboardingStatus');if(status){status.textContent=count+' / 4 complete';status.className='status-chip '+(count===4?'good':'')};
  panel.classList.toggle('complete',count===4);
}
async function loadUser(){try{const d=await api('/api/auth/user?action=me');state.dbConfigured=!!d.configured;state.user=d.user||null}catch{state.dbConfigured=false;state.user=null}
  $('#accountAction').textContent=state.user?state.user.email:'Sign in';
  $('#authForms').classList.toggle('hidden',!!state.user);$('#signedInPanel').classList.toggle('hidden',!state.user);
  $('#accountStatus').textContent=state.user?'Signed in':state.dbConfigured?'Signed out':'Database not connected';$('#accountStatus').className='status-chip '+(state.user?'good':state.dbConfigured?'':'warn');
  $$('.owner-only').forEach(el=>el.classList.toggle('hidden',state.user?.role!=='owner'));
  if(state.user){
    $('#signedInEmail').textContent=state.user.email;$('#signedInPlan').textContent=state.user.plan||'free';$('#signedInRole').textContent=state.user.role||'user';
    $('#verificationStatus').textContent=state.user.email_verified?'Email verified':'Email not verified';
    $('#verificationStatus').className='status-chip '+(state.user.email_verified?'good':'warn');
    $('#resendVerification').classList.toggle('hidden',!!state.user.email_verified);
    $('#emailIntegration').textContent=state.user.email_verified?'Verified':'Verification needed';$('#emailIntegration').className='status-chip '+(state.user.email_verified?'good':'warn');
  }else if($('#emailIntegration')){$('#emailIntegration').textContent='Sign in required';$('#emailIntegration').className='status-chip'}
  if($('#adminDbStatus')){$('#adminDbStatus').textContent=state.dbConfigured?'Connected':'Not connected';$('#adminDbStatus').className='status-chip '+(state.dbConfigured?'good':'warn')}
  updateOnboarding();return state.user}
