function pinImage(p){
  const preferred=[p?.media?.images?.originals?.url,p?.media?.images?.['1200x']?.url,p?.media?.images?.['600x']?.url,p?.media?.images?.['400x300']?.url,p?.media?.image?.url,p?.media_source?.url,p?.image?.url];
  for(const v of preferred)if(/^https?:\/\//i.test(String(v||'')))return v;
  const seen=new Set();
  function walk(v,path='',depth=0){
    if(v==null||depth>7)return'';
    if(typeof v==='string'&&/^https?:\/\//i.test(v)&&/(image|media|url|src|cover|thumbnail|original)/i.test(path))return v;
    if(typeof v!=='object'||seen.has(v))return'';seen.add(v);
    for(const [k,x] of Object.entries(v)){const found=walk(x,path+'.'+k,depth+1);if(found)return found}
    return'';
  }
  return walk(p);
}
function pinMetrics(p){const pm=p?.pin_metrics||{};return pm['90d']||pm['30d']||pm.lifetime_metrics||pm.summary_metrics||pm.all_time||pm||{}}
function metric(m,key){return Number(m?.[key]??m?.[key.toLowerCase()]??0)}
function boardName(id){return state.boards.find(b=>String(b.id)===String(id))?.name||'Pinterest Board'}
async function loadAllPins(){if(!state.productionConnected){$('#libraryNotice').textContent='Connect Pinterest to load your library.';return}state.pins=[];let bookmark='',page=0;$('#libraryNotice').className='notice';$('#libraryNotice').textContent='Loading your authorized Pin library…';try{do{const d=await api('/api/pinterest?action=pins'+(bookmark?'&bookmark='+encodeURIComponent(bookmark):''));state.pins.push(...(d.pins||[]));bookmark=d.bookmark||'';page++;$('#pinLoadProgress').textContent=fmt.format(state.pins.length)+' loaded';renderPinLibrary();renderDashboardPins();if(page>1000)throw new Error('Stopped after 250,000 Pins for browser safety.')}while(bookmark);$('#libraryNotice').className='notice success';$('#libraryNotice').textContent='Loaded '+fmt.format(state.pins.length)+' Pins from the authorized Pinterest account using API pagination.';$('#heroPins').textContent=fmt.format(state.pins.length);updateOnboarding();renderTopPins()}catch(e){$('#libraryNotice').className='notice error';$('#libraryNotice').textContent=e.message}}
function renderPinLibrary(){const q=$('#pinSearch').value.trim().toLowerCase(),board=$('#pinBoardFilter').value,sort=$('#pinSort').value;let items=state.pins.filter(p=>(!board||String(p.board_id)===board)&&(!q||String(p.title||'').toLowerCase().includes(q)||String(p.description||'').toLowerCase().includes(q)));items=items.slice();if(sort!=='newest')items.sort((a,b)=>{const ma=pinMetrics(a),mb=pinMetrics(b),k=sort==='impressions'?'IMPRESSION':sort==='saves'?'SAVE':'OUTBOUND_CLICK';return metric(mb,k)-metric(ma,k)});$('#pinGrid').innerHTML=items.map(p=>{const m=pinMetrics(p),img=pinImage(p);return '<article class="pin-card"><div class="pin-image" '+(img?'style="background-image:url(&quot;'+esc(img)+'&quot;)"':'')+'><span class="board-pill">'+esc(boardName(p.board_id))+'</span></div><div class="pin-copy"><h3>'+esc(p.title||'Untitled Pin')+'</h3><div class="pin-stats"><div class="pin-stat"><small>Impressions</small><strong>'+compact(metric(m,'IMPRESSION'))+'</strong></div><div class="pin-stat"><small>Saves</small><strong>'+compact(metric(m,'SAVE'))+'</strong></div><div class="pin-stat"><small>Pin clicks</small><strong>'+compact(metric(m,'PIN_CLICK'))+'</strong></div><div class="pin-stat"><small>Outbound</small><strong>'+compact(metric(m,'OUTBOUND_CLICK'))+'</strong></div></div><div class="pin-links"><a href="https://www.pinterest.com/pin/'+esc(p.id)+'/" target="_blank" rel="noopener">Open on Pinterest</a>'+(p.link?'<a href="'+esc(p.link)+'" target="_blank" rel="noopener">Destination</a>':'')+'</div></div></article>'}).join('')||'<div class="empty-state">No Pins match this filter.</div>'}
function renderDashboardPins(){const items=state.pins.slice(0,6);$('#dashboardPins').innerHTML=items.map(p=>{const m=pinMetrics(p),img=pinImage(p);return '<div class="mini-pin-card"><div class="image" '+(img?'style="background-image:url(&quot;'+esc(img)+'&quot;)"':'')+'></div><div class="copy"><strong>'+esc(p.title||'Untitled Pin')+'</strong><small>'+compact(metric(m,'IMPRESSION'))+' impressions</small></div></div>'}).join('')||'<div class="empty-state">No Pins loaded.</div>';if(items[0]){const img=pinImage(items[0]);$('#heroPinImage').style.backgroundImage=img?'url("'+img.replace(/"/g,'%22')+'")':'';$('#heroPinTitle').textContent=items[0].title||'Visual analytics'}}
$('#reloadPins').onclick=loadAllPins;$('#pinSearch').oninput=renderPinLibrary;$('#pinBoardFilter').onchange=renderPinLibrary;$('#pinSort').onchange=renderPinLibrary;

const METRIC_LABELS={IMPRESSION:'Impressions',ENGAGEMENT:'Engagements',SAVE:'Saves',PIN_CLICK:'Pin clicks',OUTBOUND_CLICK:'Outbound clicks',ENGAGEMENT_RATE:'Engagement rate',SAVE_RATE:'Save rate',PIN_CLICK_RATE:'Pin click rate',OUTBOUND_CLICK_RATE:'Outbound click rate',TOTAL_AUDIENCE:'Total audience',ENGAGED_AUDIENCE:'Engaged audience',MONTHLY_TOTAL_AUDIENCE:'Monthly total audience',MONTHLY_ENGAGED_AUDIENCE:'Monthly engaged audience',MONTHLY_VIEWS:'Monthly views'};
function metricValueFromDay(x,key){return Number(x?.metrics?.[key]??x?.[key]??0)}
function normalizeSeries(series,key='IMPRESSION'){return(series||[]).map(x=>({date:x.date||x.DATE||'',value:metricValueFromDay(x,key)})).filter(x=>x.date)}
function formatMetricValue(v,key){const n=Number(v||0);if(String(key).endsWith('_RATE')){const pct=Math.abs(n)<=1?n*100:n;return pct.toFixed(2)+'%'}return compact(n)}
function drawLine(canvas,series,empty,key='IMPRESSION',interactive=false){
  const pts=normalizeSeries(series,key);if(!canvas)return;
  if(!pts.length){empty?.classList.remove('hidden');const cc=canvas.getContext('2d');cc.clearRect(0,0,canvas.width,canvas.height);canvas._chartPoints=[];return}
  empty?.classList.add('hidden');const rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(300,Math.round(rect.width*dpr));canvas.height=Math.max(180,Math.round(rect.height*dpr));
  const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,p={l:22,r:14,t:18,b:28},max=Math.max(...pts.map(x=>x.value),1),min=Math.min(...pts.map(x=>x.value),0),range=max-min||1;ctx.clearRect(0,0,w,h);
  ctx.strokeStyle='#ececf2';ctx.lineWidth=1;for(let i=0;i<4;i++){const y=p.t+(h-p.t-p.b)*i/3;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke()}
  const xy=pts.map((d,i)=>({x:p.l+(w-p.l-p.r)*(pts.length===1?.5:i/(pts.length-1)),y:h-p.b-(h-p.t-p.b)*(d.value-min)/range,date:d.date,value:d.value}));
  const g=ctx.createLinearGradient(0,p.t,0,h-p.b);g.addColorStop(0,'rgba(107,76,230,.24)');g.addColorStop(1,'rgba(107,76,230,0)');
  ctx.beginPath();ctx.moveTo(xy[0].x,h-p.b);xy.forEach(q=>ctx.lineTo(q.x,q.y));ctx.lineTo(xy[xy.length-1].x,h-p.b);ctx.closePath();ctx.fillStyle=g;ctx.fill();
  ctx.beginPath();xy.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.strokeStyle='#6b4ce6';ctx.lineWidth=2.4;ctx.stroke();
  ctx.fillStyle='#6b4ce6';xy.forEach(q=>{ctx.beginPath();ctx.arc(q.x,q.y,2.3,0,Math.PI*2);ctx.fill()});
  ctx.font='8px system-ui';ctx.fillStyle='#979ba7';ctx.textAlign='center';[0,Math.floor((pts.length-1)/2),pts.length-1].forEach(i=>ctx.fillText(String(pts[i].date).slice(5),xy[i].x,h-8));
  canvas._chartPoints=xy;canvas._metricKey=key;
  if(interactive&&!canvas._hoverBound){
    canvas._hoverBound=true;
    canvas.addEventListener('mousemove',e=>{const points=canvas._chartPoints||[];if(!points.length)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left;let near=points[0];for(const pnt of points)if(Math.abs(pnt.x-x)<Math.abs(near.x-x))near=pnt;const tip=$('#analyticsTooltip');if(!tip)return;tip.innerHTML='<strong>'+esc(METRIC_LABELS[canvas._metricKey]||canvas._metricKey)+'</strong><span>'+formatMetricValue(near.value,canvas._metricKey)+'</span><small>'+esc(new Date(near.date+'T00:00:00').toLocaleDateString([],{month:'short',day:'numeric',year:'numeric'}))+'</small>';tip.style.left=Math.min(r.width-150,Math.max(8,near.x+10))+'px';tip.style.top=Math.max(8,near.y-64)+'px';tip.classList.remove('hidden')});
    canvas.addEventListener('mouseleave',()=>$('#analyticsTooltip')?.classList.add('hidden'));
  }
}
async function loadAnalytics(force=false){const days=$('#analyticsRange')?.value||30;if(state.analytics&&!force&&String(state.analytics.days)===String(days)){renderAnalytics();return}if(!state.productionConnected)return;$('#analyticsNotice').className='notice';$('#analyticsNotice').textContent='Loading live organic analytics…';try{state.analytics=await api('/api/pinterest?action=analytics&days='+days);renderAnalytics();$('#analyticsNotice').className='notice success';$('#analyticsNotice').textContent='Live authorized organic analytics loaded.'}catch(e){$('#analyticsNotice').className='notice error';$('#analyticsNotice').textContent=e.message}}
function renderAnalytics(){
  const d=state.analytics||{},m=d.summary||{};
  [['metricImpressions','IMPRESSION'],['dashImpressions','IMPRESSION'],['metricEngagements','ENGAGEMENT'],['metricSaves','SAVE'],['dashSaves','SAVE'],['metricClicks','PIN_CLICK'],['metricOutbound','OUTBOUND_CLICK'],['dashOutbound','OUTBOUND_CLICK']].forEach(([id,k])=>{const el=$('#'+id);if(el)el.textContent=formatMetricValue(metric(m,k),k)});
  const key=state.analyticsMetric||'IMPRESSION';$('#analyticsChartTitle').textContent=(METRIC_LABELS[key]||key)+' over time';
  drawLine($('#analyticsChart'),d.series,$('#analyticsChartEmpty'),key,true);drawLine($('#dashboardChart'),d.series,$('#dashboardChartEmpty'),'IMPRESSION',false);renderTopPins()
}
function renderTopPins(){const tops=state.analytics?.topPins||[];if(!tops.length){$('#topPinCards').innerHTML='<div class="empty-state">Pinterest returned no Top Pins for this range.</div>';return}$('#topPinCards').innerHTML=tops.map((t,i)=>{const p=state.pins.find(x=>String(x.id)===String(t.pin_id)),img=p?pinImage(p):'',m=t.metrics||{};return '<article class="performance-card"><div class="performance-image '+(img?'':'missing')+'" '+(img?'style="background-image:url(&quot;'+esc(img)+'&quot;)"':'')+'>'+(img?'':'<span>Image unavailable in this API response</span>')+'</div><div class="performance-copy"><span class="kicker">#'+(i+1)+'</span><strong>'+esc(p?.title||('Pin '+t.pin_id))+'</strong><small>'+compact(metric(m,'IMPRESSION'))+' impressions · '+compact(metric(m,'SAVE'))+' saves · '+compact(metric(m,'PIN_CLICK'))+' Pin clicks · '+compact(metric(m,'OUTBOUND_CLICK'))+' outbound</small></div></article>'}).join('')}
$$('.metric-toggle[data-metric]').forEach(b=>b.onclick=()=>{state.analyticsMetric=b.dataset.metric;$$('.metric-toggle').forEach(x=>x.classList.toggle('active',x===b));renderAnalytics()});
$('#refreshAnalytics').onclick=()=>loadAnalytics(true);$('#analyticsRange').onchange=()=>loadAnalytics(true);$('#refreshDashboard').onclick=async()=>{state.analytics=null;await Promise.all([loadAnalytics(true),loadSchedule()])};

