function renderVariants(container,d,onUse){container.innerHTML=(d.variants||[]).map((v,i)=>'<button class="variant-card" data-var="'+i+'"><strong>'+esc(v.title)+'</strong><p>'+esc(v.description)+'</p><span class="status-chip">'+(d.mode==='ai'?(esc(d.model||'AI')):'Smart')+' option '+(i+1)+'</span></button>').join('');container.querySelectorAll('[data-var]').forEach(b=>b.onclick=()=>onUse(d.variants[Number(b.dataset.var)]))}
