function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>resolve(r.result);r.readAsArrayBuffer(file)})}
function arrToB64(arr){let s='',u=new Uint8Array(arr),chunk=0x8000;for(let i=0;i<u.length;i+=chunk)s+=String.fromCharCode(...u.subarray(i,i+chunk));return btoa(s)}
$('#imageFile').onchange=async()=>{const f=$('#imageFile').files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)){toast('Use JPG, PNG or WebP');return}if(f.size>3*1024*1024){toast('Use an image under 3 MB for direct publishing');return}const buf=await readFile(f);state.fileBytes=buf;setImageData(arrToB64(buf),f.type,f.name,'upload')};
function stripJpegPrivate(buf){const u=new Uint8Array(buf);if(u[0]!==0xff||u[1]!==0xd8)throw new Error('Not a valid JPEG.');const parts=[u.slice(0,2)];let p=2;while(p<u.length){if(u[p]!==0xff){parts.push(u.slice(p));break}const marker=u[p+1];if(marker===0xd9||marker===0xda){parts.push(u.slice(p));break}if(p+4>u.length)break;const len=(u[p+2]<<8)|u[p+3],end=p+2+len;if(end>u.length)break;const seg=u.slice(p,end),isExif=marker===0xe1&&u[p+4]===0x45&&u[p+5]===0x78&&u[p+6]===0x69&&u[p+7]===0x66;const isComment=marker===0xfe;if(!isExif&&!isComment)parts.push(seg);p=end}const size=parts.reduce((n,x)=>n+x.length,0),out=new Uint8Array(size);let o=0;for(const x of parts){out.set(x,o);o+=x.length}return out.buffer}
function stripPngPrivate(buf){const u=new Uint8Array(buf),sig=[137,80,78,71,13,10,26,10];if(!sig.every((v,i)=>u[i]===v))throw new Error('Not a valid PNG.');const parts=[u.slice(0,8)];let p=8;while(p+12<=u.length){const len=(u[p]<<24)|(u[p+1]<<16)|(u[p+2]<<8)|u[p+3],end=p+12+len,type=String.fromCharCode(u[p+4],u[p+5],u[p+6],u[p+7]);if(end>u.length)break;if(type!=='eXIf')parts.push(u.slice(p,end));p=end;if(type==='IEND')break}const size=parts.reduce((n,x)=>n+x.length,0),out=new Uint8Array(size);let o=0;for(const x of parts){out.set(x,o);o+=x.length}return out.buffer}
$('#cleanMetadata').onclick=()=>{if(state.imageSource==='ai'){toast('AI-generated provenance is intentionally not stripped');return}if(!state.fileBytes){toast('Upload a JPEG or PNG first');return}try{let out;if(state.fileType==='image/jpeg')out=stripJpegPrivate(state.fileBytes);else if(state.fileType==='image/png')out=stripPngPrivate(state.fileBytes);else{toast('Privacy cleaning currently supports JPEG and PNG');return}state.fileBytes=out;setImageData(arrToB64(out),state.fileType,(state.fileName||'image').replace(/(\.\w+)?$/,'-privacy-clean$1'),'cleaned');toast('Private EXIF/GPS metadata removed without recompressing pixels')}catch(e){toast(e.message)}};

function imageElement(){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;if(state.fileData)img.src='data:'+state.fileType+';base64,'+state.fileData;else if(state.remoteImage){img.crossOrigin='anonymous';img.src=state.remoteImage}else resolve(null)})}
function wrapped(ctx,text,x,y,maxWidth,lineHeight,maxLines,center=false){const words=String(text||'').split(/\s+/);let line='',lines=[];for(const word of words){const t=line?line+' '+word:word;if(ctx.measureText(t).width>maxWidth&&line){lines.push(line);line=word;if(lines.length>=maxLines-1)break}else line=t}if(line&&lines.length<maxLines)lines.push(line);ctx.textAlign=center?'center':'left';lines.forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight));return lines.length}
async function makeTemplate(){const c=$('#templateCanvas'),ctx=c.getContext('2d'),style=$('#templateStyle').value,headline=$('#title').value.trim()||$('#keyword').value.trim()||state.article?.title||'Your Pin headline',footer=$('#templateFooter').value.trim()||$('#brand').value.trim()||'yourdomain.com';ctx.clearRect(0,0,c.width,c.height);let img=null;try{img=await imageElement()}catch{}if(img){const scale=Math.max(c.width/img.width,c.height/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(c.width-w)/2,(c.height-h)/2,w,h)}else{const g=ctx.createLinearGradient(0,0,c.width,c.height);g.addColorStop(0,'#e7e0ff');g.addColorStop(1,'#d6e2ef');ctx.fillStyle=g;ctx.fillRect(0,0,c.width,c.height)}if(style==='editorial'){const g=ctx.createLinearGradient(0,560,0,1500);g.addColorStop(0,'rgba(15,15,20,0)');g.addColorStop(1,'rgba(15,15,20,.88)');ctx.fillStyle=g;ctx.fillRect(0,0,1000,1500);ctx.fillStyle='#fff';ctx.font='700 82px Georgia';wrapped(ctx,headline,70,1050,850,94,4);ctx.font='700 27px Arial';ctx.fillText(footer.toUpperCase(),72,1400)}else if(style==='clean'){ctx.fillStyle='rgba(255,255,255,.93)';ctx.fillRect(55,905,890,445);ctx.fillStyle='#171820';ctx.font='700 72px Arial';wrapped(ctx,headline,95,1010,800,82,4);ctx.font='700 26px Arial';ctx.fillStyle='#6546ce';ctx.fillText(footer.toUpperCase(),97,1300)}else if(style==='bold'){ctx.fillStyle='rgba(42,27,91,.77)';ctx.fillRect(0,0,1000,1500);ctx.fillStyle='#fff';ctx.font='800 92px Arial';wrapped(ctx,headline,500,590,820,108,5,true);ctx.font='700 28px Arial';ctx.fillText(footer.toUpperCase(),500,1320)}else{ctx.fillStyle='rgba(255,255,255,.86)';ctx.fillRect(90,100,820,1300);ctx.fillStyle='#1d1d24';ctx.font='700 74px Georgia';wrapped(ctx,headline,500,520,710,88,5,true);ctx.font='700 25px Arial';ctx.fillStyle='#5b5f69';ctx.fillText(footer.toUpperCase(),500,1240)}const data=c.toDataURL('image/jpeg',.92),i=data.indexOf(',');setImageData(data.slice(i+1),'image/jpeg',(headline.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'pin')+'.jpg','template');toast('2:3 template generated')}
