function makeThumb(){return new Promise(async resolve=>{if(!state.fileData){resolve(null);return}try{const img=await imageElement(),c=document.createElement('canvas');c.width=240;c.height=360;const x=c.getContext('2d'),scale=Math.max(c.width/img.width,c.height/img.height),w=img.width*scale,h=img.height*scale;x.drawImage(img,(c.width-w)/2,(c.height-h)/2,w,h);resolve(c.toDataURL('image/jpeg',.62).split(',')[1])}catch{resolve(null)}})}
