async function loadSchedule(){if(!$('#timezoneLabel'))return;$('#timezoneLabel').textContent=Intl.DateTimeFormat().resolvedOptions().timeZone||'Local';try{const d=await api('/api/schedule');state.schedule=d.items||[];const active=state.schedule.filter(x=>x.status==='scheduled');$('#queueCount').textContent=$('#dashQueue').textContent=String(active.length);updateOnboarding();$('#queueLimit').textContent=active.length+' / '+d.limit;$('#schedulerNotice').className='notice success';$('#schedulerNotice').textContent='Persistent queue ready. Every scheduled item was explicitly approved. Background execution still needs a recurring worker trigger when the browser is closed.';renderSchedule();renderDashboardQueue(active);return true}catch(e){state.schedule=[];$('#queueCount').textContent=$('#dashQueue').textContent='0';$('#queueLimit').textContent='—';$('#schedulerNotice').className='notice';$('#schedulerNotice').textContent=e.status===401?'Create an account or sign in to use the persistent scheduler.':e.message;$('#scheduleList').innerHTML='<div class="empty-state">'+esc($('#schedulerNotice').textContent)+'</div>';renderDashboardQueue([]);return false}}
function queueImage(x){return x.image_thumb?'data:image/jpeg;base64,'+x.image_thumb:x.image_url||''}
function renderDashboardQueue(items){const upcoming=items.slice().sort((a,b)=>new Date(a.scheduled_at)-new Date(b.scheduled_at)).slice(0,4);$('#dashboardQueue').innerHTML=upcoming.map(x=>{const img=queueImage(x),d=new Date(x.scheduled_at);return '<div class="queue-item"><div class="queue-thumb" '+(img?'style="background-image:url(&quot;'+esc(img)+'&quot;)"':'')+'></div><div><strong>'+esc(x.title)+'</strong><small>'+esc(x.board_name||'Pinterest Board')+'</small></div><div class="queue-time">'+d.toLocaleDateString([],{month:'short',day:'numeric'})+'<br>'+d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+'</div></div>'}).join('')||'<div class="empty-state">Nothing scheduled yet.</div>';if(upcoming[0])$('#heroNext').textContent=new Date(upcoming[0].scheduled_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});else $('#heroNext').textContent='—'}
function renderSchedule(){const items=state.schedule.slice().sort((a,b)=>new Date(b.scheduled_at)-new Date(a.scheduled_at));$('#scheduleList').innerHTML=items.map(x=>{const d=new Date(x.scheduled_at),img=queueImage(x);return '<div class="timeline-item"><div class="timeline-time">'+d.toLocaleDateString([],{month:'short',day:'numeric'})+'<br>'+d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+'</div><div class="timeline-line"></div><div class="timeline-card"><div class="thumb" '+(img?'style="background-image:url(&quot;'+esc(img)+'&quot;)"':'')+'></div><div><strong>'+esc(x.title)+'</strong><small>'+esc(x.board_name||'Board')+(x.last_error?' · '+esc(x.last_error):'')+'</small></div><span class="status-mini '+esc(x.status)+'">'+esc(x.status)+'</span></div><div class="timeline-actions">'+(['scheduled','failed'].includes(x.status)?'<button class="secondary move-pin" data-id="'+esc(x.id)+'">Move</button> <button class="secondary cancel-pin" data-id="'+esc(x.id)+'">Cancel</button>':'')+'</div></div>'}).join('')||'<div class="empty-state">No scheduled Pins yet.</div>';$$('.cancel-pin').forEach(b=>b.onclick=async()=>{if(!confirm('Cancel this scheduled Pin?'))return;try{await api('/api/schedule?id='+encodeURIComponent(b.dataset.id),{method:'DELETE'});await loadSchedule()}catch(e){toast(e.message)}});$$('.move-pin').forEach(b=>b.onclick=async()=>{const item=state.schedule.find(x=>x.id===b.dataset.id),next=prompt('Enter a new local date/time as YYYY-MM-DD HH:MM',new Date(item.scheduled_at).toLocaleString());if(!next)return;const when=new Date(next);if(Number.isNaN(when.getTime())){toast('Invalid date/time');return}try{await api('/api/schedule',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.id,scheduled_at:when.toISOString()})});await loadSchedule();toast('Scheduled time updated')}catch(e){toast(e.message)}})}
$('#refreshSchedule').onclick=loadSchedule;$('#runDue').onclick=async()=>{if(!state.user){show('settings');return}try{const d=await post('/api/schedule?action=run-due',{});await loadSchedule();toast(d.processed?('Published '+d.processed+' due Pin(s)'):'No Pins are due right now')}catch(e){toast(e.message)}};

