async function loadWebsites(){
  const box=$('#websiteList');if(!box)return;
  if(!state.user){box.innerHTML='<div class="empty-state">Sign in to save a website connection.</div>';$('#websiteStatus').textContent='Sign in required';$('#websiteStatus').className='status-chip warn';return}
  try{
    const d=await api('/api/websites');const sites=d.sites||[];state.sites=sites;
    $('#websiteStatus').textContent=sites.length?(sites.length+' saved'):'Optional';$('#websiteStatus').className='status-chip '+(sites.length?'good':'');
    updateOnboarding();if($('#websiteIntegration')){$('#websiteIntegration').textContent=sites.length?(sites.length+' site'+(sites.length===1?'':'s')+' saved'):'Not connected';$('#websiteIntegration').className='status-chip '+(sites.length?'good':'')}box.innerHTML=sites.map(s=>'<div class="queue-item"><div class="queue-thumb" style="display:grid;place-items:center;background:#f2efff;color:#6847dc;font-weight:900">WP</div><div><strong>'+esc(s.site_name||s.site_url)+'</strong><small>'+esc(s.site_url)+'</small></div><div class="button-row"><button class="text-btn use-site" data-url="'+esc(s.site_url)+'">Use</button><button class="text-btn remove-site" data-id="'+esc(s.id)+'">Remove</button></div></div>').join('')||'<div class="empty-state">No website saved yet.</div>';
    $$('.use-site').forEach(b=>b.onclick=()=>{$('#wpSite').value=b.dataset.url;toast('Website selected — click Load posts')});
    $$('.remove-site').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this saved website connection?'))return;try{await api('/api/websites?id='+encodeURIComponent(b.dataset.id),{method:'DELETE'});await loadWebsites()}catch(e){toast(e.message)}});
  }catch(e){box.innerHTML='<div class="empty-state">'+esc(e.message)+'</div>'}
}
$('#connectWebsite').onclick=async()=>{
  if(!state.user){show('settings');toast('Sign in before saving a website');return}
  const url=$('#websiteConnectUrl').value.trim(),confirmed=$('#websiteConfirmed').checked;
  if(!url){toast('Enter your public WordPress site URL');return}
  if(!confirmed){toast('Confirm you own or are authorized to use this site');return}
  try{const d=await post('/api/websites',{site_url:url,site_name:new URL(url.startsWith('http')?url:'https://'+url).hostname,kind:'wordpress-public',confirmed:true});$('#wpSite').value=d.site_url||url;$('#websiteConnectUrl').value='';$('#websiteConfirmed').checked=false;await loadWebsites();toast('Website saved. You can now load its published posts.')}catch(e){toast(e.message)}
};

async function loadAdmin(){
  if(state.user?.role!=='owner')return;
  try{
    const d=await api('/api/admin?action=status');state.admin=d;
    $('#adminAiStatus').textContent=d.ai.configured?'Configured':'Not configured';$('#adminAiStatus').className='status-chip '+(d.ai.configured?'good':'warn');
    $('#adminEmailStatus').textContent=d.email.configured?'Configured':'Not configured';$('#adminEmailStatus').className='status-chip '+(d.email.configured?'good':'warn');
    $('#adminTextModels').value=(d.ai.textModels||[]).join('\n');$('#adminImageModels').value=(d.ai.imageModels||[]).join('\n');$('#adminDefaultPrompt').value=d.ai.defaultPrompt||'';
    $('#adminTextCost').value=d.ai.costs?.text??1;$('#adminImageLowCost').value=d.ai.costs?.image?.low??4;$('#adminImageMediumCost').value=d.ai.costs?.image?.medium??8;$('#adminImageHighCost').value=d.ai.costs?.image?.high??14;
    $('#adminEmailFrom').value=d.email.from||'';$('#adminUserCount').textContent=(d.users?.length||0)+' users';
    $('#adminUsers').innerHTML=(d.users||[]).map(u=>'<tr><td>'+esc(u.email)+'</td><td><span class="status-chip '+(u.role==='owner'?'good':'')+'">'+esc(u.role)+'</span></td><td>'+(u.email_verified?'<span class="status-chip good">Verified</span>':'<span class="status-chip warn">Pending</span>')+'</td><td><strong>'+fmt.format(Number(u.ai_credits||0))+'</strong></td><td><div class="credit-adjust"><input type="number" value="10" class="credit-delta" data-user="'+esc(u.id)+'"><button class="secondary add-credits" data-user="'+esc(u.id)+'">Apply</button></div></td></tr>').join('')||'<tr><td colspan="5">No users yet.</td></tr>';
    $$('.add-credits').forEach(b=>b.onclick=async()=>{const input=$('.credit-delta[data-user="'+b.dataset.user+'"]'),delta=Number(input?.value||0);if(!delta){toast('Enter a non-zero credit adjustment');return}try{await post('/api/admin?action=credits',{user_id:b.dataset.user,delta,reason:'Owner console adjustment'});await loadAdmin();if(state.user?.id===b.dataset.user)await loadAI();toast('Credits updated')}catch(e){toast(e.message)}});
    await Promise.all([loadBilling(),loadStatus()]);
  }catch(e){toast(e.message)}
}
$('#refreshAdmin').onclick=loadAdmin;
$('#saveAISettings').onclick=async()=>{try{await post('/api/admin?action=save-ai',{api_key:$('#adminOpenAIKey').value,text_models:$('#adminTextModels').value,image_models:$('#adminImageModels').value,default_prompt:$('#adminDefaultPrompt').value,costs:{text:Number($('#adminTextCost').value||1),image:{low:Number($('#adminImageLowCost').value||4),medium:Number($('#adminImageMediumCost').value||8),high:Number($('#adminImageHighCost').value||14)}}});$('#adminOpenAIKey').value='';await Promise.all([loadAdmin(),loadAI()]);$('#adminAiNotice').className='notice success';$('#adminAiNotice').textContent='AI provider settings saved. The key is encrypted and is never sent to workspace users.'}catch(e){$('#adminAiNotice').className='notice error';$('#adminAiNotice').textContent=e.message}};
$('#syncOpenAIModels').onclick=async()=>{try{const d=await api('/api/admin?action=models');if(d.textModels?.length)$('#adminTextModels').value=d.textModels.join('\n');if(d.imageModels?.length)$('#adminImageModels').value=d.imageModels.join('\n');$('#adminAiNotice').className='notice success';$('#adminAiNotice').textContent='Available model IDs loaded from the configured OpenAI account. Review the list and save only models you want customers to use.'}catch(e){$('#adminAiNotice').className='notice error';$('#adminAiNotice').textContent=e.message}};
$('#saveEmailSettings').onclick=async()=>{try{await post('/api/admin?action=save-email',{api_key:$('#adminResendKey').value,from:$('#adminEmailFrom').value});$('#adminResendKey').value='';await loadAdmin();$('#adminEmailNotice').className='notice success';$('#adminEmailNotice').textContent='Email settings saved. New users can receive verification links once the sender domain is accepted by the mail provider.'}catch(e){$('#adminEmailNotice').className='notice error';$('#adminEmailNotice').textContent=e.message}};

async function loadIntegrations(){await Promise.all([loadUser(),loadStatus(),loadAI(),loadWebsites()])}
async function refreshSettings(){await loadUser();await loadStatus()}
$('#disconnectPinterest').onclick=async()=>{if(!confirm('Disconnect Pinterest from this browser?'))return;try{await post('/api/pinterest?action=disconnect',{});state.productionConnected=false;await loadStatus();toast('Pinterest disconnected from this browser')}catch(e){toast(e.message)}};

async function quietDue(){if(!state.user)return;try{const d=await post('/api/schedule?action=run-due',{});if(d.processed)await loadSchedule()}catch{}}
async function init(){setDefaultSchedule();updatePreview();await Promise.all([loadUser(),loadStatus(),loadAI()]);await loadAccount();if(state.productionConnected){await Promise.all([loadAnalytics(true),loadAllPins()])}await loadSchedule();await syncCheckout();const q=new URLSearchParams(location.search);if(q.get('verified')){await loadUser();show('settings');toast('Email verified successfully')}else if(q.get('signup')){show('settings');authMode='signup';$$('.auth-tab').forEach(x=>x.classList.toggle('active',x.dataset.auth==='signup'));$('#authSubmit').textContent='Create account';$('#authPassword').autocomplete='new-password'}else if(q.get('login')){show('settings')}else if(q.get('oauth')){show(q.get('oauth')==='sandbox-connected'?'integrations':'create');if(state.user&&q.get('oauth')==='connected')toast('Pinterest connected. Scheduler authorization saved for this workspace.')}setInterval(quietDue,60000)}
window.addEventListener('resize',()=>{if(state.analytics){drawLine($('#dashboardChart'),state.analytics.series,$('#dashboardChartEmpty'),'IMPRESSION',false);drawLine($('#analyticsChart'),state.analytics.series,$('#analyticsChartEmpty'),state.analyticsMetric||'IMPRESSION',true)}});
init();